CREATE SCHEMA IF NOT EXISTS stall_booking;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, legal_name=EXCLUDED.legal_name, email=EXCLUDED.email;

ON CONFLICT (tenant_id, event_code) DO UPDATE SET event_name=EXCLUDED.event_name, venue_name=EXCLUDED.venue_name, status=EXCLUDED.status;


