ON CONFLICT (tenant_id, email) DO UPDATE SET full_name=EXCLUDED.full_name, password_hash=EXCLUDED.password_hash, is_active=true;

SELECT u.tenant_id, u.event_id, u.id, r.id, current_date, true, now() FROM stall_booking.users u JOIN stall_booking.roles r ON r.tenant_id=u.tenant_id AND r.event_id=u.event_id AND ((u.email='superadmin@lubmsmehosur.org' AND r.role_code='SuperAdmin') OR (u.email='eventadmin@lubmsmehosur.org' AND r.role_code='EventAdmin') OR (u.email='stallallocation@lubmsmehosur.org' AND r.role_code='StallAllocationAdmin') OR (u.email='payment@lubmsmehosur.org' AND r.role_code='PaymentVerifier') OR (u.email='invoice@lubmsmehosur.org' AND r.role_code='ProformaInvoicePreparer') OR (u.email='committee@lubmsmehosur.org' AND r.role_code='CoreCommitteeMember') OR (u.email='auditor@lubmsmehosur.org' AND r.role_code='ViewerAuditor'))
ON CONFLICT (tenant_id, event_id, user_id, role_id) DO UPDATE SET is_active=true;

